-- Repeatable local-only seed data. Passwords are generated by pgcrypto and are
-- for local development only; never reuse these credentials in production.
INSERT INTO app_user (id, username, username_normalized, password_hash, nickname, status)
VALUES
    (
        '00000000-0000-0000-0000-000000000001',
        'admin',
        'admin',
        crypt('Admin@12345', gen_salt('bf', 12)),
        '演示管理员',
        'ACTIVE'
    ),
    (
        '00000000-0000-0000-0000-000000000002',
        'student01',
        'student01',
        crypt('Student@12345', gen_salt('bf', 12)),
        '演示用户',
        'ACTIVE'
    )
ON CONFLICT (username_normalized) DO NOTHING;

INSERT INTO user_role (user_id, role)
SELECT id, 'ADMIN' FROM app_user WHERE username_normalized = 'admin'
ON CONFLICT DO NOTHING;

INSERT INTO user_role (user_id, role)
SELECT id, 'USER' FROM app_user WHERE username_normalized = 'student01'
ON CONFLICT DO NOTHING;

